INSERT IGNORE INTO books (id, title, author, genre, total_sales, total_rating, rating_count, price, description) VALUES
(1, '三体', '刘慈欣', '科幻', 2500000, 4.8, 128000, 45.00, '文化大革命期间，一次秘密的军事项目向宇宙发出了地球文明的信号，从此人类的命运被彻底改变。这是一部将中国科幻文学推向世界高度的经典之作，讲述了地球文明与三体文明之间跨越数百年的宇宙博弈。'),
(2, '活着', '余华', '文学', 2000000, 4.9, 156000, 28.00, '地主少爷福贵嗜赌成性，终于赌光了家业一贫如洗。穷困之中的福贵因为母亲生病前去求医，没想到半路上被国民党部队抓了壮丁。经过几番波折回到家里，却发现母亲早已去世。此后他经历了人生中一次次的生离死别，最后只剩一头老牛与他相依为命。'),
(3, '百年孤独', '加西亚·马尔克斯', '文学', 800000, 4.5, 68000, 55.00, '布恩迪亚家族七代人的传奇故事，以及加勒比海沿岸小镇马孔多的百年兴衰，反映了拉丁美洲一个世纪以来风云变幻的历史。作品融入神话传说、民间故事、宗教典故等神秘因素，巧妙地糅合了现实与虚幻。'),
(4, '小王子', '圣埃克苏佩里', '文学', 1500000, 4.7, 98000, 32.00, '飞行员因飞机故障迫降在撒哈拉沙漠，遇见了来自B-612小行星的小王子。小王子向飞行员讲述了自己游历各个星球的见闻，以及他与玫瑰、狐狸的故事。这是一部写给大人的童话，关于爱、责任与纯真。'),
(5, '人类简史', '尤瓦尔·赫拉利', '历史', 1200000, 4.6, 76000, 68.00, '十万年前，地球上至少有六种不同的人，但今日，世界舞台上为什么只剩下我们自己？从认知革命、农业革命到科学革命，我们真的了解自己吗？我们过得更快乐吗？本书从宏观视角梳理了人类的发展历程。'),
(6, '围城', '钱钟书', '文学', 900000, 4.4, 54000, 36.00, '围在城里的人想逃出来，城外的人想冲进去。方鸿渐留洋归来，在爱情、事业、婚姻的围城中进进出出。钱钟书以幽默辛辣的笔触，写尽了人情世态的微妙与荒诞。'),
(7, '解忧杂货店', '东野圭吾', '小说', 1100000, 4.3, 82000, 49.50, '僻静的街道旁有一家杂货店，只要写下烦恼投进店前门卷帘门的投信口，第二天就会在店后的牛奶箱里得到回答。三个迷途的年轻人误入这家已经废弃的杂货店，意外收到了来自过去的信件，由此展开了一段跨越时空的温暖故事。'),
(8, '平凡的世界', '路遥', '文学', 1000000, 4.8, 91000, 108.00, '这是一部全景式地表现中国当代城乡社会生活的长篇小说。孙少安与孙少平两兄弟在大时代的变迁中，不断超越苦难，展现了普通人在社会变革浪潮中所走过的艰难曲折的道路，讴歌了普通劳动者的奋斗精神。'),
(9, '射雕英雄传', '金庸', '武侠', 1800000, 4.7, 102000, 56.00, '南宋年间，郭靖与黄蓉相识于江湖，一路习武历练、保家卫国。金庸以恢弘的笔力构建了一个快意恩仇的武侠世界，「侠之大者，为国为民」的精神影响了一代又一代读者。'),
(10, '白夜行', '东野圭吾', '推理', 1600000, 4.6, 95000, 59.00, '1973年大阪的一栋废弃建筑内发现了一具男尸，此后19年间，案件相关者的命运诡谲交错。全书没有一句正面描写，却让读者在碎片中拼出一段绝望而隐秘的关系，被誉为东野圭吾的巅峰之作。'),
(11, '明朝那些事儿', '当年明月', '历史', 2200000, 4.8, 135000, 99.00, '从朱元璋出生写到大明王朝落幕，以史料为基础、以年代和人物为主线，用小说的笔法对明朝十七帝和其他王公权贵、小人物的命运进行全景展示，把历史写得妙趣横生。'),
(12, '哈利·波特与魔法石', 'J.K.罗琳', '童话', 3000000, 4.7, 168000, 49.00, '在女贞路4号碗柜里住了十年的哈利，十一岁生日那天收到了霍格沃茨魔法学校的入学信。九又四分之三站台的列车，带他和读者一起进入了一个瑰丽的魔法世界，这是一代人的童年记忆。'),
(13, '西游记', '吴承恩', '神话', 1500000, 4.8, 128000, 39.50, '东胜神洲石猴出世，大闹天宫，后被压五行山下五百年，随唐僧西行取经，一路降妖伏魔。吴承恩以天马行空的想象构建了一个神魔交织的世界，师徒四人的取经历程也是一场关于成长与修行的寓言。'),
(14, '许三观卖血记', '余华', '文学', 980000, 4.7, 76000, 35.00, '丝厂送茧工许三观靠着一次次卖血，撑过了人生里的大灾小难：儿子闯祸、饥荒岁月、儿子重病……余华以近乎喜剧的笔调讲述一个悲凉的故事，写尽了一个普通父亲笨拙而滚烫的爱。'),
(15, '飞鸟集', '泰戈尔', '诗歌', 680000, 4.6, 54000, 25.00, '「夏天的飞鸟，飞到我的窗前唱歌，又飞去了。」泰戈尔以三百余首清丽小诗，写飞鸟、流萤、落叶与繁星，在自然的意象中藏着哲思与温柔，被誉为「世界上最美的诗集」之一。'),
(16, '长安的荔枝', '马伯庸', '小说', 1150000, 4.5, 68000, 45.00, '天宝十四年，长安城的小吏李善德接下一个不可能的任务：在贵妃诞辰前，把岭南的新鲜荔枝运到五千余里外的长安。荔枝「一日色变，两日香变，三日味变」，他要用算学与实干，跑赢这场与时间的赛跑。'),
(17, '红楼梦', '曹雪芹', '文学', 1200000, 4.9, 148000, 59.00, '女娲补天遗石下凡历劫，绛珠仙草以泪还恩。曹雪芹以贾府的兴衰为主线，描绘了大观园中宝玉、黛玉、宝钗等人的命运沉浮，写尽世情百态，被誉为中国古典小说的巅峰之作。'),
(18, '福尔摩斯探案集', '阿瑟·柯南·道尔', '推理', 1800000, 4.6, 112000, 68.00, '雾气弥漫的伦敦贝克街221B号，咨询侦探福尔摩斯与华生医生搭档，以缜密的演绎法破解一桩桩离奇案件。柯南·道尔开创了侦探小说的黄金时代，「演绎法」的魅力影响了后世所有推理作品。'),
(19, '银河帝国：基地', '艾萨克·阿西莫夫', '科幻', 850000, 4.7, 62000, 88.00, '数学家哈里·谢顿创立「心理史学」，预见到银河帝国将在三百年内崩溃，人类将陷入三万年的黑暗。为缩短黑暗时代，他在银河边缘建立「基地」，一座以保存文明火种为使命的孤岛。科幻大师阿西莫夫的传世三部曲开篇。'),
(20, '被讨厌的勇气', '岸见一郎/古贺史健', '心理学', 2000000, 4.5, 138000, 55.00, '「被讨厌」是自由生活的证据。一位青年与一位哲人，围绕阿德勒心理学展开五夜辩论：烦恼皆源于人际关系，课题分离是解决的钥匙，而幸福，是拥有甘于平凡的勇气。以对话体写就的心理自助经典。'),
(21, '呐喊', '鲁迅', '文学', 750000, 4.7, 92000, 25.00, '「铁屋中的呐喊」。收录《狂人日记》《孔乙己》《阿Q正传》《故乡》等十四篇作品，鲁迅以冷峻而滚烫的笔触，写尽国民的麻木与觉醒，为新文化运动划破了时代的沉默。'),
(22, '追风筝的人', '卡勒德·胡赛尼', '小说', 4500000, 4.8, 218000, 39.00, '阿富汗少爷阿米尔与仆人之子哈桑情同手足，却在一场风筝比赛后因懦弱犯下过错。多年后，一句「为你，千千万万遍」召唤他重返故土，踏上自我救赎之路。一个关于背叛与救赎的动人故事。'),
(23, '球状闪电', '刘慈欣', '科幻', 900000, 4.6, 58000, 38.00, '一道球状闪电夺走了少年的父母，他用一生追问它的本质。从弦论到量子态，从军事应用到宏电子，刘慈欣用硬核的想象把一个自然之谜推向宇宙尺度的浪漫，这也是「三体宇宙」的前传。'),
(24, '盗墓笔记', '南派三叔', '悬疑', 3200000, 4.2, 175000, 78.00, '五十年前长沙镖子岭的一次盗掘，牵出战国帛书里的惊天秘密。吴邪跟随三叔的脚步踏入七星鲁王宫，与张起灵、王胖子组成铁三角，开启了对长白山青铜门背后「终极」的十年追寻。'),
(25, '枪炮、病菌与钢铁', '贾雷德·戴蒙德', '历史', 850000, 4.5, 66000, 78.00, '为什么是欧亚大陆的文明征服了美洲，而不是相反？戴蒙德用「地理决定论」给出惊世解答：粮食生产的差异、可驯化物种的分布、大陆轴线的走向，早已写下了各民族命运的起点。'),
(26, '苏菲的世界', '乔斯坦·贾德', '哲学', 2100000, 4.4, 118000, 49.00, '十四岁的苏菲收到两封神秘的信：「你是谁？」「世界从何而来？」在神秘导师的引导下，她开始了一堂横贯两千余年的哲学课——从苏格拉底到萨特，而真相远比课程本身更加惊人。'),
(27, '天龙八部', '金庸', '武侠', 1600000, 4.8, 128000, 65.00, '乔峰的豪迈、段誉的痴、虚竹的憨，三兄弟在辽宋纷争的乱世中结义同行。「无人不冤，有情皆孽」，金庸以佛家视角写尽贪嗔痴的宿命，堪称武侠文学的巅峰鸿篇。'),
(28, '无人生还', '阿加莎·克里斯蒂', '推理', 1800000, 4.6, 98000, 35.00, '十个素不相识的人被邀请到孤岛上的别墅，晚餐时留声机响起，逐一指控每个人的罪状。随后，死亡按照童谣的方式接连降临……封闭空间与童谣杀人的开山之作，推理女王的传世经典。'),
(29, '傲慢与偏见', '简·奥斯汀', '文学', 950000, 4.5, 87000, 36.00, '伊丽莎白·班纳特聪明独立，达西先生富有而矜持。初见时的傲慢与偏见，在乡村舞会、庄园漫步与书信往来中层层化解。奥斯汀以轻盈幽默的笔触，写出了爱情与婚姻中最清醒的答案。'),
(30, '克拉拉与太阳', '石黑一雄', '小说', 600000, 4.3, 45000, 59.00, '克拉拉是一台太阳能人工智能机器人，以观察者的纯净目光注视着人类世界。她被病弱的女孩乔西带回家，承诺用尽一切方式守护她。诺奖作家石黑一雄借机器之眼，叩问爱与人心的本质。');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(1, '中国科幻的巅峰之作，宏大的宇宙观让人震撼，黑暗森林法则的设定尤其精彩，读完久久不能平静。', '豆瓣', 5.0, '正面', 0.92, '科幻,震撼,黑暗森林,宇宙观', '星际旅人', 856, 124, '2026-09-25 10:30:00'),
(1, '第一部最惊艳，第二部格局更大，第三部结局略显仓促，但整体仍是神作级别。', '豆瓣', 5.0, '正面', 0.85, '神作,格局,结局', '读书人小王', 432, 56, '2026-09-27 14:22:00'),
(1, '人物塑造相对薄弱，女性角色刻画扁平，但科幻创意确实一流。', '知乎', 3.5, '中性', 0.05, '人物,角色,创意', '文学青年', 218, 89, '2026-09-29 09:15:00'),
(1, '脑洞大到超出想象，叶文洁的抉择、面壁计划、降维打击，每一个概念都令人叫绝。', '豆瓣', 5.0, '正面', 0.88, '脑洞,降维打击,面壁计划', '宇宙尘埃', 654, 78, '2026-10-01 20:45:00'),
(1, '翻译腔和理科生文笔稍显生硬，前100页有点难熬，但坚持下来后欲罢不能。', '微信读书', 4.0, '正面', 0.42, '文笔,翻译,难熬', '小学生家长', 156, 34, '2026-10-04 16:30:00'),
(1, '黑色森林理论细思极恐，对人性与文明的思考非常深刻，强烈推荐。', '豆瓣', 5.0, '正面', 0.90, '黑暗森林,人性,文明,推荐', '思想者', 389, 45, '2026-10-08 11:20:00'),
(1, '结尾的圣母心设定我不太能接受，前面铺垫那么久，结局有点崩。', '知乎', 2.0, '负面', -0.65, '结局,圣母,崩', '理性的读者', 275, 156, '2026-10-12 19:40:00'),
(1, '程心这个角色写得太气人了，但这也正是刘慈欣想表达的东西吧。', '微信读书', 4.0, '中性', 0.10, '程心,角色,表达', '云天明', 198, 210, '2026-10-16 21:10:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(2, '一口气读完，哭得稀里哗啦。福贵的一生就是中国最苦难年代的缩影，写得太真实了。', '豆瓣', 5.0, '正面', 0.95, '感人,真实,苦难', '晚风', 1024, 156, '2026-09-24 22:10:00'),
(2, '余华的文字朴素却有千钧之力，把悲剧写得平静克制，反而更让人心痛。', '微信读书', 5.0, '正面', 0.90, '文字,悲剧,克制', '麦田守望者', 687, 89, '2026-09-26 15:35:00'),
(2, '看完之后心情压抑了好几天，太惨了，不建议心情不好的时候读。', '知乎', 3.0, '负面', -0.45, '压抑,惨,心情', '小确幸', 345, 201, '2026-09-28 13:50:00'),
(2, '人是为了活着本身而活着，而不是为了活着之外的任何事物而活着。这句话值五颗星。', '豆瓣', 5.0, '正面', 0.88, '活着,哲理,经典', '行路人', 512, 67, '2026-10-02 08:25:00'),
(2, '有庆死的那一段，我到现在都不敢回想。余华太狠心了。', '微信读书', 4.5, '中性', -0.05, '有庆,虐心', '柠檬不酸', 423, 98, '2026-10-05 17:45:00'),
(2, '结构精巧，以民谣采集者的视角讲述，让苦难多了一层温度。', '知乎', 5.0, '正面', 0.82, '结构,叙事,视角', '文学分析家', 234, 32, '2026-10-09 12:00:00'),
(2, '应该是每个人必读的中国文学作品，理解上一辈人的苦难从这里开始。', '豆瓣', 5.0, '正面', 0.91, '必读,文学,苦难', '书虫阿花', 478, 54, '2026-10-13 20:15:00'),
(2, '结尾老牛福贵的画面太绝了，苦难尽头是平静，这本书我每年都要重读一遍。', '微信读书', 5.0, '正面', 0.93, '结尾,重读,平静', '老书友', 356, 41, '2026-10-17 09:40:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(3, '魔幻现实主义的巅峰，家族七代人的命运循环让人着迷，就是名字实在太难记了。', '豆瓣', 4.5, '正面', 0.78, '魔幻现实主义,家族,名字', '拉美文学爱好者', 456, 78, '2026-09-26 11:30:00'),
(3, '读了两遍才理清人物关系，但第二遍读出了完全不同的味道，值得。', '知乎', 4.5, '正面', 0.72, '人物关系,重读', '耐心读者', 312, 45, '2026-09-30 16:20:00'),
(3, '开头是文学史上最伟大的开头之一，羊皮卷的宿命设定太精妙了。', '豆瓣', 5.0, '正面', 0.85, '开头,宿命,精妙', '读书笔记君', 289, 34, '2026-10-03 14:10:00'),
(3, '翻译有些拗口，读到一半放弃了，可能是我境界不够。', '微信读书', 2.5, '负面', -0.55, '翻译,放弃,拗口', '躺平的书友', 198, 123, '2026-10-06 19:35:00'),
(3, '孤独是这本书的主题，每个人都在用自己的方式对抗孤独，最后都失败了。', '知乎', 5.0, '正面', 0.80, '孤独,主题,命运', '深夜书桌', 367, 56, '2026-10-10 22:50:00'),
(3, '雷梅黛丝抓着床单升天的画面，多年后依然忘不掉，这就是文学的魅力。', '豆瓣', 4.5, '正面', 0.75, '魔幻,画面,升天', '白日梦想家', 245, 38, '2026-10-14 10:05:00'),
(3, '节奏太慢，人物太多，读得很累，不太适合我。', '微信读书', 2.0, '负面', -0.60, '节奏,人物,累', '快节奏患者', 156, 87, '2026-10-18 15:30:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(4, '看似童话，实则写尽成年人世界的荒诞。驯养与责任那段，每次读都会流泪。', '豆瓣', 5.0, '正面', 0.94, '童话,驯养,责任,感动', '玫瑰与狐狸', 789, 102, '2026-09-25 18:20:00'),
(4, '「重要的东西用眼睛是看不见的」，这句话我要抄在笔记本第一页。', '微信读书', 5.0, '正面', 0.90, '金句,哲理', '小学生的妈妈', 456, 56, '2026-09-28 09:10:00'),
(4, '很适合亲子共读，孩子喜欢星球冒险的部分，我被狐狸的话打动了。', '知乎', 4.5, '正面', 0.76, '亲子,共读,狐狸', '宝爸宝妈', 324, 41, '2026-10-01 15:40:00'),
(4, '篇幅太短了，意犹未尽，但也许短小正是它的完美之处。', '豆瓣', 4.5, '正面', 0.70, '篇幅,短小', '爱书的猫', 187, 25, '2026-10-05 21:15:00'),
(4, '不同年龄读有不同的感悟，十岁读是童话，三十岁读是人生。', '微信读书', 5.0, '正面', 0.88, '年龄,感悟,人生', '而立之年', 512, 73, '2026-10-09 11:55:00'),
(4, '插画很美，译本质量参差不齐，建议选口碑好的版本。', '知乎', 4.0, '中性', 0.15, '插画,译本,版本', '版本控', 143, 30, '2026-10-13 16:25:00'),
(4, '给孩子买的第一本书，希望他能像小王子一样保持纯真。', '豆瓣', 5.0, '正面', 0.86, '孩子,纯真,礼物', '新手爸爸', 265, 35, '2026-10-16 20:35:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(5, '认知革命、农业革命、科学革命的框架清晰有力，讲故事的能力一流，刷新了我对历史的认知。', '豆瓣', 4.5, '正面', 0.82, '认知革命,框架,历史,新颖', '理性思考者', 567, 89, '2026-09-27 13:25:00'),
(5, '观点新颖但有些论断缺乏严谨的学术支撑，当作思想启发读物很好，当历史教科书不行。', '知乎', 4.0, '中性', 0.08, '观点,学术,严谨', '历史专业生', 389, 156, '2026-09-30 20:40:00'),
(5, '虚构故事这一章太精彩了，公司、国家、货币都是想象的共同体，这个视角值回书价。', '微信读书', 5.0, '正面', 0.87, '虚构,想象,共同体', '好奇星人', 456, 67, '2026-10-03 17:15:00'),
(5, '后半部分关于快乐与生物学的讨论有点跑题，整体不如前半部分精彩。', '豆瓣', 3.5, '中性', 0.02, '后半部分,跑题,快乐', '挑剔读者', 212, 78, '2026-10-07 10:30:00'),
(5, '读完对人类这个物种又爱又恨，作者的野心和格局让人佩服。', '知乎', 4.5, '正面', 0.75, '物种,格局,佩服', '宏观视野', 298, 42, '2026-10-11 14:50:00'),
(5, '翻译流畅，阅读体验很好，适合作为通识入门书推荐给学生。', '微信读书', 4.5, '正面', 0.70, '翻译,入门,推荐', '中学老师', 234, 28, '2026-10-15 09:20:00'),
(5, '部分章节的因果关系太简化了，作者太爱下大结论，需要批判性地读。', '知乎', 3.0, '负面', -0.40, '简化,结论,批判', '较真的人', 187, 95, '2026-10-18 19:05:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(6, '钱钟书的比喻句句见血，幽默里全是刻薄，刻薄里全是真实，堪称中文写作教科书。', '豆瓣', 5.0, '正面', 0.89, '比喻,幽默,真实,教科书', '文字爱好者', 678, 92, '2026-09-26 16:45:00'),
(6, '城外的人想冲进去，城里的人想逃出来。婚姻如此，职业如此，人生莫不如此。', '知乎', 5.0, '正面', 0.85, '围城,婚姻,人生', '过来人', 534, 87, '2026-10-01 11:35:00'),
(6, '方鸿渐优柔寡断的样子太真实了，我们每个人身上都有他的影子。', '微信读书', 4.5, '正面', 0.72, '方鸿渐,真实,共鸣', '打工人小张', 412, 65, '2026-10-04 20:25:00'),
(6, '讽刺力度很足，但故事性偏弱，情节推进比较平，读起来需要耐心。', '豆瓣', 3.5, '中性', 0.00, '讽刺,情节,耐心', '故事优先党', 198, 56, '2026-10-08 13:55:00'),
(6, '女生们不要嫁方鸿渐，男人们不要学方鸿渐，这本书是本反面教材合集（褒义）。', '知乎', 4.5, '正面', 0.65, '婚姻,教材,讽刺', '犀利姐', 345, 112, '2026-10-12 17:30:00'),
(6, '苏文纨和唐晓芙写得真好，一个端着，一个灵动，钱钟书写女性很有一手。', '微信读书', 5.0, '正面', 0.80, '女性角色,苏文纨,唐晓芙', '文学少女', 276, 44, '2026-10-16 12:10:00'),
(6, '重读发现年轻时只看懂了幽默，现在才看懂了悲哀。', '豆瓣', 5.0, '正面', 0.83, '重读,幽默,悲哀', '中年读者', 398, 51, '2026-10-19 21:45:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(7, '东野圭吾少有的温情之作，几个故事的时间线最后交汇在一起时，起了鸡皮疙瘩。', '豆瓣', 4.5, '正面', 0.80, '温情,故事,时间线,惊喜', '悬疑迷', 456, 67, '2026-09-27 19:20:00'),
(7, '结构精巧，但说教味有点浓，每个问题的答案都太「正确」了，少了点真实感。', '知乎', 3.5, '中性', 0.10, '结构,说教,正确', '毒舌书评人', 287, 98, '2026-10-02 14:15:00'),
(7, '浪矢爷爷认真回复每一封信的态度太治愈了，「人的心声是绝对不能无视的」。', '微信读书', 5.0, '正面', 0.88, '治愈,温暖,心声', '需要被治愈的人', 523, 72, '2026-10-05 10:50:00'),
(7, '比起东野圭吾的推理小说，这本明显套路化，属于快餐读物。', '知乎', 2.5, '负面', -0.50, '套路,推理,快餐', '本格推理粉', 234, 134, '2026-10-09 16:35:00'),
(7, '鱼店音乐人的故事看得我泪流满面，梦想与现实的抉择写得太动人。', '豆瓣', 5.0, '正面', 0.86, '梦想,现实,感人,音乐', '追梦人', 389, 55, '2026-10-13 22:05:00'),
(7, '适合冬天窝在被子里一口气读完的书，暖。', '微信读书', 4.5, '正面', 0.74, '治愈,温暖,轻松', '冬日暖阳', 198, 23, '2026-10-17 13:25:00'),
(7, '中文版翻译流畅，装帧精美，但内容深度一般，读一遍就够了。', '知乎', 3.5, '中性', 0.05, '翻译,装帧,深度', '理性购书者', 145, 38, '2026-10-20 11:15:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(8, '孙少平在煤矿里读书的画面，是我心中文学史上最动人的场景之一。普通人的奋斗最动人。', '豆瓣', 5.0, '正面', 0.92, '奋斗,孙少平,感人,经典', '黄土高坡', 892, 134, '2026-09-28 12:40:00'),
(8, '三部曲的体量很大，读了一个月，但完全不觉得漫长，路遥的文字有一种踏实的力量。', '知乎', 5.0, '正面', 0.87, '体量,文字,力量,踏实', '长篇爱好者', 467, 58, '2026-10-01 18:30:00'),
(8, '田晓霞的死让我哭了一晚上，为什么好人没有好报，太虐了。', '微信读书', 4.5, '负面', -0.35, '田晓霞,虐心,结局', '意难平', 556, 187, '2026-10-04 23:20:00'),
(8, '对黄土高原风土人情的描写非常扎实，是一部了解陕北社会的百科全书。', '豆瓣', 5.0, '正面', 0.84, '陕北,风土人情,扎实', '民俗爱好者', 312, 41, '2026-10-08 09:55:00'),
(8, '价值观有点老派，孙少安和贺秀莲的婚姻观放在今天争议很大。', '知乎', 3.5, '中性', -0.05, '价值观,婚姻,争议', '新时代青年', 278, 143, '2026-10-12 15:40:00'),
(8, '获得茅盾文学奖实至名归，每一代年轻人都能从孙氏兄弟身上看到自己。', '微信读书', 5.0, '正面', 0.90, '茅盾文学奖,经典,年轻人', '书评人老周', 423, 66, '2026-10-15 20:10:00'),
(8, '路遥写完这本书累垮了身体，用生命写作的作品，字里行间全是诚意。', '豆瓣', 5.0, '正面', 0.88, '路遥,生命,诚意', '敬路人', 367, 49, '2026-10-18 14:30:00'),
(8, '第二部节奏有些拖沓，可以适当跳读，不影响整体。', '知乎', 4.0, '中性', 0.12, '节奏,拖沓,跳读', '效率阅读者', 156, 33, '2026-10-20 19:50:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(9, '金庸武侠的入门与巅峰，郭靖的笨拙坚毅、黄蓉的聪慧灵动，侠之大者为国为民，百读不厌。', '豆瓣', 5.0, '正面', 0.90, '武侠,经典,侠义', '江湖夜雨', 823, 118, '2026-09-25 15:10:00'),
(9, '黄蓉是我心中最完美的文学形象之一，聪明伶俐又不失深情，翁美玲就是从书里走出来的。', '微信读书', 5.0, '正面', 0.88, '黄蓉,人物,灵动', '桃花岛主', 512, 76, '2026-09-29 10:40:00'),
(9, '前期铺垫略慢，江南七怪教武功那段可以快进，但从郭靖遇黄蓉开始就停不下来了。', '知乎', 4.0, '中性', 0.10, '节奏,铺垫,慢', '急性子书友', 245, 52, '2026-10-02 16:25:00'),
(9, '降龙十八掌出场必配BGM，华山论剑、桃花岛招亲，名场面一个接一个，看得热血沸腾。', '豆瓣', 4.5, '正面', 0.78, '降龙十八掌,热血,名场面', '武侠迷阿飞', 389, 61, '2026-10-05 21:30:00'),
(9, '主角光环太重，郭靖的每次奇遇都恰到好处，反派又全都没脑子，武侠终究是成人童话。', '知乎', 2.5, '负面', -0.50, '主角光环,理想化,童话', '现实主义者', 267, 141, '2026-10-09 14:15:00'),
(9, '重读才读懂「侠之大者」，襄阳城头的郭靖不只是大侠，更是中国人骨子里的担当。', '微信读书', 5.0, '正面', 0.85, '家国,担当,重读', '中年书友', 456, 68, '2026-10-13 09:50:00'),
(9, '感情线有些套路化，几个姑娘都围着男主转，放到现在大概会被吐槽。', '豆瓣', 3.5, '中性', 0.00, '感情线,套路,配角', '新时代读者', 187, 79, '2026-10-16 19:35:00'),
(9, '我的武侠启蒙书，从此掉进金学的坑里爬不出来，全套已集齐。', '知乎', 4.5, '正面', 0.80, '启蒙,金庸,收藏', '金迷一枚', 298, 37, '2026-10-19 22:05:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(10, '全书没有一句正面描写两人的关系，却句句都是他们，这种叙事功力真的绝了。', '豆瓣', 5.0, '正面', 0.85, '叙事,留白,震撼', '推理界扛把子', 756, 109, '2026-09-26 13:45:00'),
(10, '看完久久缓不过来，不是吓的，是那种从头凉到脚的绝望。我的天空里没有太阳。', '知乎', 5.0, '正面', 0.88, '绝望,致郁,震撼', '深夜读者', 634, 152, '2026-09-30 21:20:00'),
(10, '东野圭吾把伏笔埋得太深了，最后一章全部收拢，19年的时间线严丝合缝。', '微信读书', 4.5, '正面', 0.80, '伏笔,结构,时间线', '细节控', 423, 57, '2026-10-03 18:55:00'),
(10, '太黑暗太压抑了，通篇没有一个好人，读完对人性都产生怀疑了，慎入。', '豆瓣', 3.0, '负面', -0.45, '黑暗,压抑,慎入', '阳光爱好者', 312, 168, '2026-10-07 12:30:00'),
(10, '桐原亮司和唐泽雪穗到底是不是爱情？争论了这么多年，这正是这本书的魅力。', '知乎', 4.5, '中性', 0.05, '爱情,人性,争议', '文学辩论家', 289, 196, '2026-10-10 20:15:00'),
(10, '社会派的巅峰之作，每一个配角的案子都不是孤立的，拼图式的阅读体验独一无二。', '豆瓣', 5.0, '正面', 0.86, '社会派,拼图,经典', '东野书迷', 367, 48, '2026-10-14 16:40:00'),
(10, '雪穗美则美矣，也太可怕了，这种黑莲花人设现在想想脊背发凉。', '微信读书', 4.0, '中性', -0.10, '雪穗,可怕,人设', '吃瓜群众', 245, 88, '2026-10-17 15:25:00'),
(10, '结尾那句话我记了很多年，她一次都没有回头。意难平。', '知乎', 5.0, '正面', 0.82, '结局,意难平,经典', '老书虫', 478, 72, '2026-10-20 11:50:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(11, '把枯燥的历史写得比小说还好看，当年明月是历史圈最会讲故事的人，没有之一。', '豆瓣', 5.0, '正面', 0.92, '历史,通俗,有趣', '历史小白', 934, 128, '2026-09-27 14:35:00'),
(11, '朱棣、于谦、张居正、王阳明，每个人物都写活了，看完对明朝如数家珍。', '知乎', 5.0, '正面', 0.88, '人物,明朝,生动', '当年书粉', 567, 83, '2026-10-01 10:20:00'),
(11, '北京保卫战于谦那段看哭了，「社稷为重，君为轻」，气节二字重千斤。', '微信读书', 5.0, '正面', 0.85, '于谦,气节,感动', '粉身碎骨浑不怕', 489, 92, '2026-10-04 19:10:00'),
(11, '作者主观色彩比较浓，很多历史事件的解读带戏说成分，当消遣读物可以，别当史料。', '知乎', 3.5, '中性', 0.08, '主观,戏说,史料', '历史系学生', 345, 167, '2026-10-08 15:45:00'),
(11, '结尾写徐霞客收笔，「成功只有一个——按照自己的方式，去度过人生」，全书立意瞬间升华。', '豆瓣', 5.0, '正面', 0.87, '结尾,徐霞客,哲理', '人间清醒', 623, 96, '2026-10-11 22:30:00'),
(11, '我的明史启蒙书，当年上学偷偷在被窝里看的，现在给孩子买了全套。', '微信读书', 4.5, '正面', 0.80, '启蒙,入门,推荐', '老读者', 401, 54, '2026-10-14 13:05:00'),
(11, '越到后面质量越下降，崇祯朝写得太仓促，有种虎头蛇尾的感觉。', '知乎', 3.0, '负面', -0.40, '后期,仓促,质量', '挑剔的书友', 234, 101, '2026-10-17 17:20:00'),
(11, '幽默是外衣，悲凉是内核，笑着笑着就看哭了，王朝兴衰尽在其中。', '豆瓣', 5.0, '正面', 0.83, '幽默,悲凉,兴衰', '看史之人', 356, 61, '2026-10-19 20:55:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(12, '十岁那年收到猫头鹰来信是我的梦想，罗琳构建的魔法世界是一代人共同的童年。', '豆瓣', 5.0, '正面', 0.93, '魔法,童年,梦想', '麻瓜小学生', 1024, 156, '2026-09-26 17:15:00'),
(12, '时隔二十年重读依然热血，分院帽、魁地奇、厄里斯魔镜，每个设定都精妙绝伦。', '知乎', 5.0, '正面', 0.90, '重读,设定,热血', '霍格沃茨校友', 687, 98, '2026-09-30 09:35:00'),
(12, '作为系列第一本，悬念铺陈恰到好处，孩子一口气看完，缠着我马上买第二部。', '微信读书', 4.5, '正面', 0.78, '悬念,孩子,入门', '陪读家长', 423, 45, '2026-10-03 20:50:00'),
(12, '人名翻译各版本差异太大，赫敏还是妙丽？建议认准人文社官方版本。', '豆瓣', 4.0, '中性', 0.15, '翻译,版本,人名', '版本收集癖', 289, 76, '2026-10-06 14:25:00'),
(12, '对成年人来说剧情太简单了，正邪分明缺少灰度，童话终究是童话。', '知乎', 3.0, '负面', -0.35, '低龄,简单,童话', '重口味读者', 198, 113, '2026-10-09 18:40:00'),
(12, '厄里斯魔镜那段写得太好了，「沉湎于虚幻的梦想而忘记现实的生活，这是毫无益处的」。', '豆瓣', 5.0, '正面', 0.88, '魔镜,哲理,成长', '魔法史教授', 456, 62, '2026-10-12 16:55:00'),
(12, '和朋友约好一起去九又四分之三站台打卡，这本书就是青春的入场券。', '微信读书', 4.5, '正面', 0.82, '站台,青春,回忆', '格兰芬多', 334, 51, '2026-10-15 21:05:00'),
(12, '斯内普这个角色第一本就被误读了，多年后回头看全是伏笔，罗琳布局之深令人叹服。', '知乎', 5.0, '正面', 0.86, '斯内普,伏笔,布局', '蛇院卧底', 578, 87, '2026-10-18 12:45:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(13, '从小看到大的一部神作，孙悟空大闹天宫的桥段百看不厌，想象力的天花板。', '豆瓣', 5.0, '正面', 0.92, '想象力,经典,神话', '花果山常客', 912, 134, '2026-09-25 10:30:00'),
(13, '取经路上八十一难，难难不同，其实写的就是人这一辈子要过的坎。', '知乎', 5.0, '正面', 0.90, '师徒,成长,坚持', '取经人', 654, 89, '2026-09-28 15:20:00'),
(13, '吴承恩的幽默感被严重低估，猪八戒的憨态和书里的讽刺都妙极。', '微信读书', 4.5, '正面', 0.80, '幽默,讽刺,笔法', '八戒粉丝', 432, 56, '2026-10-01 19:10:00'),
(13, '小时候看的是删减版，长大后读原著才发现不少诗词被砍了，建议读人民文学出版社全本。', '豆瓣', 4.0, '中性', 0.15, '版本,删减,原著', '版本控', 276, 63, '2026-10-05 11:45:00'),
(13, '中段降妖除魔套路重复感明显，读起来有些疲劳，影视版已经把精华提炼得更好。', '知乎', 3.0, '负面', -0.30, '重复,套路,冗长', '快节奏读者', 187, 95, '2026-10-08 20:35:00'),
(13, '孙悟空前期蔑视一切规则的野性，和后来戴上紧箍咒的约束，是中国文学里最动人的成长寓言。', '豆瓣', 5.0, '正面', 0.88, '悟空,自由,成长', '齐天大圣', 523, 71, '2026-10-11 17:00:00'),
(13, '和孩子一起读的，他迷上金箍棒，我重读出了职场味，各取所需其乐融融。', '微信读书', 4.5, '正面', 0.84, '亲子,共读,启蒙', '宝妈读书会', 298, 38, '2026-10-14 21:25:00'),
(13, '四大名著里最适合孩子入门的一部，读罢再看国漫崛起，才懂我们的神话宝库多深厚。', '知乎', 5.0, '正面', 0.87, '四大名著,必读,文化', '文化自信派', 445, 66, '2026-10-17 13:40:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(14, '许三观为一乐一路卖血卖到上海的情节看得我眼眶发热，底层父爱写得太扎实。', '豆瓣', 5.0, '正面', 0.93, '温情,苦难,父爱', '纸巾预备者', 876, 121, '2026-09-26 14:20:00'),
(14, '用最朴素的白描写出最汹涌的情感，余华的黑色幽默让人笑着笑着就哭了。', '知乎', 5.0, '正面', 0.91, '余华,黑色幽默,笔力', '余华门徒', 612, 84, '2026-09-29 16:55:00'),
(14, '「炒菜」那几段的口头重复真绝，声音一响，红烧肉就端上桌了，堪称文字蒙太奇。', '微信读书', 4.5, '正面', 0.86, '口头,重复,叙事', '饥饿共鸣者', 478, 59, '2026-10-02 12:35:00'),
(14, '时代感太强，读着压抑，不是随时都有勇气翻开的那种书。', '豆瓣', 4.0, '中性', 0.12, '时代,沉重,压抑', '心情管理师', 234, 47, '2026-10-06 09:50:00'),
(14, '相比《活着》少了些命运的重量，女性角色写得略显单薄。', '知乎', 3.0, '负面', -0.28, '平淡,单薄,人物', '比较阅读党', 176, 88, '2026-10-09 22:10:00'),
(14, '结尾许三观想吃炒猪肝却没人再要他的血，那种被时代抛下的失落，是全书最狠一笔。', '豆瓣', 5.0, '正面', 0.90, '结局,释然,岁月', '炒猪肝爱好者', 534, 77, '2026-10-12 18:25:00'),
(14, '比《活着》更好读的一本余华，篇幅短、对话多，推荐作为余华入门。', '微信读书', 4.5, '正面', 0.83, '入门,推荐,余华', '入门导游', 356, 42, '2026-10-15 20:15:00'),
(14, '一乐不是亲生的却最像他，这个设定本身就写尽了人性和亲情的荒诞与真实。', '知乎', 5.0, '正面', 0.89, '人性,亲情,感动', '泪腺失守', 489, 68, '2026-10-18 15:50:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(15, '三百多句小诗，每句都像一颗露珠，落在心上清凉又透亮，生如夏花之绚烂就出自这里。', '豆瓣', 5.0, '正面', 0.90, '诗意,哲思,短句', '夏花与秋叶', 723, 96, '2026-09-27 08:40:00'),
(15, '枕边常备诗集，失眠随手翻一页，总能被某句轻轻接住。', '微信读书', 4.5, '正面', 0.85, '枕边,治愈,重读', '夜读星人', 398, 45, '2026-10-01 22:30:00'),
(15, '郑振铎的译本也是诗，「夏天的飞鸟，飞到我的窗前唱歌，又飞去了」，读出声才懂它的好。', '知乎', 5.0, '正面', 0.88, '翻译,郑振铎,经典', '朗读派', 512, 73, '2026-10-04 14:55:00'),
(15, '有人读出禅意，有人觉得是心灵鸡汤的古典版，见仁见智，篇幅太短不够解渴。', '豆瓣', 4.0, '中性', 0.08, '风格,简约,见仁见智', '中肯点评家', 203, 52, '2026-10-07 16:20:00'),
(15, '对现在的我来说略显空洞，哲理式短句读多了有审美疲劳。', '知乎', 3.0, '负面', -0.25, '空洞,鸡汤,审美疲劳', '硬核读者', 154, 61, '2026-10-10 19:05:00'),
(15, '泰戈尔把飞鸟、流萤、落叶都写活了，万物在他笔下都有灵性，太温柔了。', '微信读书', 4.5, '正面', 0.82, '自然,意象,温柔', '万物有灵', 287, 34, '2026-10-13 10:10:00'),
(15, '高中时手抄过整本送人，是我的青春纪念册，金句密度天花板。', '豆瓣', 5.0, '正面', 0.87, '礼物,手抄,摘抄', '手抄本持有者', 341, 49, '2026-10-16 13:30:00'),
(15, '世界诗歌最好的入门读物之一，成本很低，收获很大。', '知乎', 4.5, '正面', 0.81, '世界文学,入门,经典', '诗歌安利员', 219, 29, '2026-10-19 17:45:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(16, '「一骑红尘妃子笑」背后是小人物的血泪，把岭南荔枝运到长安的难题，放今天就是极限 deadline 的项目，打工人读来字字共鸣。', '豆瓣', 5.0, '正面', 0.89, '职场,共鸣,小人物', '荔枝使同僚', 668, 102, '2026-09-28 12:15:00'),
(16, '马伯庸的历史可能性写作又一次成功，节奏快、考据足，一个周末就能读完。', '知乎', 4.5, '正面', 0.84, '马伯庸,节奏,爽感', '周末读者', 521, 64, '2026-10-02 15:40:00'),
(16, '李善德用算学硬啃转运路线那段太燃了，实干型主角谁不爱。', '微信读书', 4.5, '正面', 0.83, '李善德,算法,实干', '工科生的浪漫', 389, 47, '2026-10-05 19:55:00'),
(16, '篇幅短是双刃剑，后半段收得略仓促，阿僮姑娘的线意犹未尽。', '豆瓣', 4.0, '中性', 0.10, '篇幅,仓促,结尾', '意犹未尽者', 245, 39, '2026-10-08 21:20:00'),
(16, '人物动机和转折太工整，像命题作文，少了点意外的生命力。', '知乎', 3.0, '负面', -0.22, '套路,网文,工整', '挑剔书评人', 168, 72, '2026-10-11 18:00:00'),
(16, '「流程，是弱者才要遵循的规矩」，这句台词值得所有职场人裱起来，讽刺得又准又狠。', '豆瓣', 5.0, '正面', 0.87, '台词,讽刺,深刻', '裱起来的人', 476, 85, '2026-10-14 11:25:00'),
(16, '看完专门去查了唐代荔枝保鲜和驿传制度，一本小说勾起一串历史知识点，值回票价。', '微信读书', 4.5, '正面', 0.80, '历史,科普,荔枝', '考据小能手', 267, 33, '2026-10-17 16:35:00'),
(16, '「就算失败，我也想知道，自己倒在距离终点多远的地方」，就冲这句也值五星。', '知乎', 4.5, '正面', 0.82, '愿力,初心,感动', '李善德本人', 402, 58, '2026-10-20 14:10:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(17, '千古绝唱。人物群像刻画入木三分，大观园的兴衰就是一部人间百态，每读一遍都有新的感悟。', '豆瓣', 5.0, '正面', 0.94, '经典,人物,兴衰,百态', '潇湘夜雨', 921, 156, '2026-09-24 09:20:00'),
(17, '曹公的笔力深不可测，随便一个丫鬟都写得有血有肉，诗词曲赋处处见功夫，值得反复品读。', '微信读书', 5.0, '正面', 0.88, '经典,笔力,诗词', '红迷一枚', 567, 98, '2026-09-27 20:15:00'),
(17, '文学价值毋庸置疑，但阅读门槛确实高，人物关系复杂，需要边读边画族谱，适合静下心慢慢啃。', '知乎', 4.0, '中性', 0.55, '门槛,人物,复杂', '格物致知', 342, 89, '2026-09-30 14:40:00'),
(17, '林黛玉进贾府那段描写堪称教科书级别，未见其人先闻其声，王熙凤的形象跃然纸上。', '豆瓣', 5.0, '正面', 0.91, '描写,人物,经典', '稻香村客', 445, 67, '2026-10-04 10:55:00'),
(17, '后半部分续书的争议一直存在，读到最后总感觉气韵不如前八十回，不过整体仍是不可逾越的高峰。', '微信读书', 3.5, '中性', 0.50, '续书,争议,高峰', '版本考据控', 289, 112, '2026-10-08 19:05:00'),
(17, '说实话有点读不下去，节奏太慢，日常琐事太多，可能是我境界不够吧，尝试三次都弃在三十回。', '知乎', 2.5, '负面', 0.78, '节奏,慢,弃读', '快节奏选手', 198, 234, '2026-10-12 21:30:00'),
(17, '一部封建社会的百科全书，饮食服饰园林礼仪无所不包，考据党能从中挖出无数细节，太牛了。', '豆瓣', 5.0, '正面', 0.90, '百科全书,细节,考据', '文字考古', 634, 88, '2026-10-16 11:10:00'),
(17, '高中被语文老师安利入坑，如今三十岁重读，终于读懂了「落了片白茫茫大地真干净」的苍凉。', '小红书', 5.0, '正面', 0.87, '重读,苍凉,结局', '一颗橘子', 387, 65, '2026-10-19 17:45:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(18, '推理小说的鼻祖，演绎法的魅力经久不衰。福尔摩斯和华生的搭档堪称文学史上最成功的组合。', '豆瓣', 5.0, '正面', 0.93, '推理,鼻祖,演绎法', '贝克街221B', 768, 112, '2026-09-25 15:30:00'),
(18, '《血字的研究》《红发会》《斑点带子案》……短篇案子篇篇精彩，疑云密布到揭底的过程特别过瘾。', '知乎', 5.0, '正面', 0.86, '短篇,精彩,过瘾', '卷帘人', 456, 78, '2026-09-29 12:20:00'),
(18, '经典归经典，但读多了套路感明显，福尔摩斯几乎无所不能，现代推理作品更注重公平性。', '微信读书', 3.5, '中性', 0.52, '套路,公平,经典', '本格爱好者', 301, 95, '2026-10-03 16:45:00'),
(18, '柯南·道尔对伦敦雾气的描写太有氛围感了，配上插图读仿佛置身维多利亚时代的贝克街。', '豆瓣', 5.0, '正面', 0.90, '氛围,伦敦,插图', '雾都迷案', 398, 54, '2026-10-06 09:35:00'),
(18, '翻译版本差异很大，选对译本很重要。我买的这版翻译生硬，建议先试读再入手。', '知乎', 3.0, '中性', 0.58, '翻译,版本,译本', '买书如山倒', 267, 143, '2026-10-10 13:50:00'),
(18, '年代久远导致节奏偏慢，铺垫冗长，案情反转以现代眼光看并不意外，更适合文学爱好者而非推理迷。', '微信读书', 2.5, '负面', 0.72, '年代,节奏,反转', '推理评测君', 213, 187, '2026-10-13 20:05:00'),
(18, '华生医生不只是工具人，他的忠诚与幽默让故事有了温度，两个人抬杠的日常太可爱了。', '小红书', 5.0, '正面', 0.89, '华生,搭档,幽默', '草莓酱', 523, 69, '2026-10-17 10:25:00'),
(18, '最后一案福尔摩斯坠落莱辛巴赫瀑布时真的哭了，还好后来复活了，侦探文学永远的神。', '豆瓣', 5.0, '正面', 0.85, '最后一案,复活,神作', '退休侦探', 612, 101, '2026-10-20 18:40:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(19, '心理史学太震撼了！把历史发展变成可以计算的公式，谢顿计划的宏大布局让人拍案叫绝。', '豆瓣', 5.0, '正面', 0.91, '心理史学,谢顿,震撼', '基地fan', 534, 89, '2026-09-26 14:10:00'),
(19, '阿西莫夫的格局无人能及，一个帝国的兴衰浓缩在几百年间，科幻史学的开创之作。', '知乎', 5.0, '正面', 0.85, '格局,帝国,开创', '骡与第二基地', 412, 66, '2026-09-30 11:25:00'),
(19, '系列开篇立意极高，但人物塑造相对单薄，更像设定集与历史书，喜欢硬核设定的会爱不释手。', '微信读书', 3.5, '中性', 0.54, '人物,设定,硬核', '设定党', 287, 74, '2026-10-04 15:50:00'),
(19, '1950年代的作品至今毫不违和，「骡」这个变量的出现打破谢顿预言的设计太妙了。', '豆瓣', 4.5, '正面', 0.88, '骡,预言,巧妙', '川陀旅人', 356, 58, '2026-10-07 19:35:00'),
(19, '对话推动剧情的方式略显枯燥，场景转换基本靠讲述，读起来需要一点耐心，啃完前传再来评。', '知乎', 3.0, '中性', 0.49, '对话,节奏,耐心', '银河纪年', 198, 87, '2026-10-11 10:05:00'),
(19, '别被盛名骗了，文风干巴巴的，翻译腔也重，所谓反转就是换主角继续讲故事，三本弃评。', '微信读书', 2.5, '负面', 0.75, '文风,翻译,弃评', '直球书评', 176, 203, '2026-10-14 16:20:00'),
(19, '川陀、端星、提弗……银河世界的地理想象令人神往，第二基地的悬念设计堪称系列最佳。', '豆瓣', 5.0, '正面', 0.87, '银河,悬念,最佳', '谢顿信徒', 445, 72, '2026-10-18 13:45:00'),
(19, '看完基地再去看《基地与帝国》和《第二基地》，三部曲连读体验最佳，阿西莫夫宇宙的大门从此打开。', '小红书', 5.0, '正面', 0.83, '三部曲,连读,宇宙', '星舰小兔', 389, 61, '2026-10-21 15:55:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(20, '阿德勒心理学入门神作！「一切烦恼都来自人际关系」这句话直接点醒我，对话体读起来毫无门槛。', '豆瓣', 5.0, '正面', 0.90, '阿德勒,烦恼,人际关系', '课题分离中', 876, 203, '2026-09-25 20:30:00'),
(20, '「课题分离」四个字值回书价，分清谁的课题就不再内耗，读完对职场人际关系通透了很多。', '知乎', 5.0, '正面', 0.86, '课题分离,内耗,通透', '不上班的第3年', 654, 98, '2026-09-28 09:45:00'),
(20, '观点很激进，「目的论」全盘否定创伤的存在让我难以接受，部分论述有以偏概全之嫌，辩证着看吧。', '微信读书', 3.0, '中性', 0.52, '目的论,创伤,激进', '心理学研究生', 387, 156, '2026-10-02 14:55:00'),
(20, '青年与哲人的辩论太真实了，青年的每一次反驳都是我想问的，被说服的过程就像自己也被治愈了。', '小红书', 5.0, '正面', 0.88, '对话,治愈,辩论', '小小太阳花', 498, 77, '2026-10-05 18:20:00'),
(20, '鸡汤浓度略高，案例都是理想化的，实际运用起来并不容易，「被讨厌的勇气」说起来简单做起来难。', '知乎', 3.0, '中性', 0.48, '鸡汤,案例,实践', '人间清醒组', 298, 134, '2026-10-09 11:35:00'),
(20, '同样的内容反复车轱辘话说五轮，一句话能讲完的道理写了一整本，看目录直接读划线句就够了。', '豆瓣', 2.5, '负面', 0.73, '重复,冗长,划线', '效率至上', 245, 178, '2026-10-12 15:00:00'),
(20, '「重要的不是被给予了什么，而是如何去使用被给予的东西」，这句话贴在了我的工位上，每天看一遍。', '微信读书', 5.0, '正面', 0.84, '金句,使用,自我', '打工人小裴', 567, 85, '2026-10-16 20:10:00'),
(20, '甘于平凡的勇气这一章写得最好，接受普通的自己也是一种勇敢，今年读到的最治愈的一本书。', '小红书', 5.0, '正面', 0.89, '平凡,勇气,治愈', '慢慢来的小满', 423, 69, '2026-10-19 16:25:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(21, '每个中国人都会在某一刻读懂鲁迅。《狂人日记》里「救救孩子」的呼喊，一百年后依然震耳欲聋。', '豆瓣', 5.0, '正面', 0.90, '鲁迅,狂人日记,觉醒', '铁屋子里的光', 845, 167, '2026-09-24 10:15:00'),
(21, '孔乙己是站着喝酒而穿长衫的唯一的人——一句话就立起一个人物，中学时不懂，读懂已是书中人。', '微信读书', 5.0, '正面', 0.87, '孔乙己,人物,经典', '回字有四样写法', 623, 102, '2026-09-27 15:40:00'),
(21, '教材节选太多导致捧读原著时有些陌生，白话文初期的语言习惯需要适应，但思想锋利度无解。', '知乎', 4.0, '中性', 0.52, '语言,教材,锋利', '语感考古', 312, 85, '2026-10-01 11:20:00'),
(21, '阿Q的精神胜利法是刻进民族基因的镜子，每次生活受挫想起「儿子打老子」都会苦笑，然后脊背发凉。', '豆瓣', 5.0, '正面', 0.92, '阿Q,精神胜利,镜子', '未庄观察员', 534, 96, '2026-10-05 19:30:00'),
(21, '《社戏》《兔和猫》几篇相对平淡，前半震撼后半稍缓，但仅凭《故乡》里「其实地上本没有路」就值五星。', '微信读书', 3.5, '中性', 0.48, '节奏,故乡,平淡', '月光与猹', 267, 58, '2026-10-09 14:05:00'),
(21, '学生时代被逼着背了太多课文，现在一翻开就有应激反应，需要时间治愈再重新品味，暂时差评。', '知乎', 2.5, '负面', 0.70, '课文,应激,回忆', '被背诵支配的恐惧', 189, 213, '2026-10-12 20:45:00'),
(21, '「从来如此，便对么？」狂人这句发问是全书最锋利的一刀，独立之精神莫过于此。', '小红书', 5.0, '正面', 0.89, '狂人,发问,锋利', '拾荒的思想者', 456, 79, '2026-10-16 09:50:00'),
(21, '《药》的结尾那只铁铸般的乌鸦让人难忘，鲁迅的冷峻之下全是滚烫，常读常新的国民读本。', '豆瓣', 5.0, '正面', 0.85, '药,乌鸦,冷峻', '华老栓茶馆', 398, 61, '2026-10-20 17:25:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(22, '「为你，千千万万遍」——这句话看完之后每次想起都会鼻酸。背叛与救赎写得如此戳心，谁没当过胆小的阿米尔呢。', '豆瓣', 5.0, '正面', 0.93, '救赎,背叛,戳心', '追风的少年', 912, 234, '2026-09-25 21:10:00'),
(22, '哈桑的忠诚让人心碎，「他只是个哈桑」那声回答之后，眼泪根本止不住。阿富汗的风土人情也写得很鲜活。', '知乎', 5.0, '正面', 0.88, '哈桑,忠诚,阿富汗', '石榴树下', 654, 118, '2026-09-29 13:25:00'),
(22, '前半段极好，后半段救赎之路走向俗套的圆满，巧合太多削弱了力量，但仍是值得一读的催泪之作。', '微信读书', 3.5, '中性', 0.50, '俗套,巧合,圆满', '冷静书虫', 298, 92, '2026-10-03 16:50:00'),
(22, '「那儿有再次成为好人的路」，这句推荐语就是全书的答案。读完后我开始想自己人生里那只没追上的风筝。', '小红书', 5.0, '正面', 0.90, '救赎,好人的路,风筝', '夜跑的橘子', 512, 86, '2026-10-07 10:35:00'),
(22, '文学性一般，叙事技巧偏通俗，某些桥段设计感太强，胜在情感真挚，适合入门读者。', '知乎', 3.0, '中性', 0.47, '通俗,设计感,真挚', '文学批评社', 276, 143, '2026-10-10 15:55:00'),
(22, '被眼泪滤镜抬得太高，情节推进靠巧合堆叠，人物善恶脸谱化，读一半就猜到结局。', '豆瓣', 2.5, '负面', 0.68, '巧合,脸谱化,结局', '理中客书评', 223, 197, '2026-10-13 18:20:00'),
(22, '战前喀布尔的明媚与战后的疮痍对比太扎心，借一个孩子的童年写尽一个国家的哀伤。', '微信读书', 5.0, '正面', 0.86, '喀布尔,对比,哀伤', '风筝线断了', 445, 67, '2026-10-17 12:40:00'),
(22, '父辈的秘密与孩子的救赎两代呼应，「当罪行导致善行，那就是真正的获救」，读完整个人都静下来了。', '知乎', 5.0, '正面', 0.87, '获救,秘密,呼应', '石榴籽', 487, 74, '2026-10-20 19:05:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(23, '大刘把「浪漫」写进了物理公式里：飘在空中的量子玫瑰，是科幻迷能想到最极致的温柔。', '豆瓣', 5.0, '正面', 0.90, '量子玫瑰,浪漫,硬核', '宏电子观察员', 567, 98, '2026-09-26 14:50:00'),
(23, '比三体更聚焦，「观察者」设定的哲学意味和军事科幻的结合太妙了，林云这个角色又飒又让人心疼。', '知乎', 5.0, '正面', 0.85, '观察者,林云,军事', '弦论小白', 423, 71, '2026-09-30 10:05:00'),
(23, '前面悬疑感拉满，中段物理设定铺陈略干，不熟悉弦论概念的读者会有点吃力，坚持到结尾绝对值。', '微信读书', 3.5, '中性', 0.55, '设定,物理,吃力', '量子态的路人', 287, 66, '2026-10-04 16:30:00'),
(23, '泰阳号那段宏聚变的光景想象震撼到失语，大刘写大场面从来不会让人失望。', '豆瓣', 4.5, '正面', 0.88, '宏聚变,震撼,场面', '陈博士的实验室', 345, 54, '2026-10-07 20:15:00'),
(23, '人物服务于设定痕迹明显，感情线生硬，纯粹当硬科幻看不错，想看文学性的绕行。', '知乎', 3.0, '中性', 0.46, '人物,感情线,设定', '挑剔的读者', 198, 89, '2026-10-11 13:40:00'),
(23, '结局强行升华，量子态的设定前后矛盾，前期营造的紧张感虎头蛇尾，不如三体好看。', '微信读书', 2.5, '负面', 0.72, '结局,矛盾,虎头蛇尾', '三体优先党', 176, 167, '2026-10-14 17:55:00'),
(23, '把球状闪电这个民间之谜写成了宇宙级浪漫，「美妙人生的关键在于你能迷上什么东西」，金句频出。', '小红书', 5.0, '正面', 0.84, '金句,谜题,浪漫', '吹泡泡的丁仪', 389, 62, '2026-10-18 11:30:00'),
(23, '看完球闪再看三体，会解锁很多隐藏彩蛋（丁仪、宏原子），大刘宇宙的连载感太爽了。', '知乎', 4.5, '正面', 0.86, '彩蛋,丁仪,联动', '横贯欧亚的电网', 412, 58, '2026-10-21 15:15:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(24, '铁三角的羁绊是全部核心，「用我一生换你十年天真无邪」的设定太戳人，从书追到剧再到漫画。', '豆瓣', 5.0, '正面', 0.85, '铁三角,羁绊,十年之约', '稻米十年', 823, 198, '2026-09-25 22:20:00'),
(24, '七星鲁王宫和云顶天宫两大篇章封神，地下世界的氛围营造让初中时的我看得头皮发麻又停不下来。', '知乎', 4.5, '正面', 0.82, '氛围,鲁王宫,云顶', '夜宿青铜门', 512, 121, '2026-09-29 17:35:00'),
(24, '挖坑不填是原罪！青铜门后的「终极」至今语焉不详，后期设定崩坏明显，情怀在撑分。', '微信读书', 3.0, '中性', 0.45, '挖坑,终极,崩坏', '十级考据稻米', 387, 176, '2026-10-03 19:50:00'),
(24, '王胖子承包全书笑点，吴邪从天真到成熟的变化写得好，大篇幅冒险描写读起来一气呵成。', '小红书', 4.5, '正面', 0.80, '笑点,成长,冒险', '胖爷的铲子', 456, 83, '2026-10-06 21:05:00'),
(24, '越写越长越写越散，番外比正文还多，续作迭代质量参差，建议只读前五部。', '知乎', 3.0, '中性', 0.52, '番外,散,前五部', '理性追更党', 267, 134, '2026-10-10 12:25:00'),
(24, '恐怖氛围靠一堆「禁婆」「尸蹩」名词堆砌，逻辑硬伤不少，后期主角光环太重，纯靠情怀。', '豆瓣', 2.5, '负面', 0.72, '逻辑,硬伤,情怀', '盗墓科普君', 213, 187, '2026-10-13 14:45:00'),
(24, '十年之约长白山接小哥那章，虽然是网络文学却写出了史诗感，青春的一部分，五星给回忆。', '小红书', 5.0, '正面', 0.78, '十年之约,长白山,青春', '接小哥回家', 634, 152, '2026-10-16 22:10:00'),
(24, '前四部精彩，五部之后水字数明显，秦岭神树可以一读，整体起伏太大。', '微信读书', 3.0, '中性', 0.50, '水字数,秦岭,起伏', '补完计划中', 245, 76, '2026-10-19 13:35:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(25, '用地理解释文明命运的宏大叙事，大陆轴线理论把人类史讲成了自然科学，读完看世界的方式变了。', '豆瓣', 5.0, '正面', 0.90, '地理,文明,大陆轴线', '演化论者', 543, 92, '2026-09-26 11:40:00'),
(25, '亚力的问题开篇即巅峰，粮食生产-牲畜-病菌的因果链条环环相扣，论证严密得像论文一样扎实。', '知乎', 5.0, '正面', 0.85, '粮食,病菌,论证', '读书破万卷的猫', 398, 67, '2026-09-30 15:55:00'),
(25, '「地理决定论」解释了起点却解释不了终点，对文化和制度的变量着墨太少，论证有循环之嫌，但仍是必读。', '微信读书', 3.5, '中性', 0.52, '地理,制度,循环', '制度经济学徒', 287, 104, '2026-10-04 18:10:00'),
(25, '为什么是欧洲人带着枪炮病菌去美洲，而不是印加帝国反过来？这个问题的答案比任何悬疑小说都精彩。', '小红书', 5.0, '正面', 0.87, '枪炮,美洲,精彩', '南美土豆', 356, 58, '2026-10-08 13:25:00'),
(25, '翻译生硬读着累，后半部分案例重复论证啰嗦，核心观点前两章就讲完了，快速阅读即可。', '知乎', 3.0, '中性', 0.48, '翻译,重复,啰嗦', '效率阅读者', 245, 98, '2026-10-11 20:35:00'),
(25, '披着科学外衣的宿命论，把文明差异全归因地理有失偏颇，论据选择性明显，读着读着就不信了。', '豆瓣', 2.5, '负面', 0.70, '宿命论,偏颇,论据', '历史系在读', 213, 187, '2026-10-14 12:50:00'),
(25, '病菌一章最震撼：欧亚人与家畜共处千年换来的抗体，成了殖民时代最致命的武器，历史就是这样残酷。', '微信读书', 4.5, '正面', 0.84, '病菌,抗体,殖民', '天花毯子', 312, 71, '2026-10-18 16:05:00'),
(25, '跨学科写作的典范，生物学、语言学、考古学信手拈来，虽然个别论断被后续研究修正，框架依然惊人。', '知乎', 4.5, '正面', 0.83, '跨学科,考古,框架', '更新世的猎人', 276, 49, '2026-10-21 10:20:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(26, '最好的哲学启蒙书没有之一。跟着苏菲从苏格拉底一路走到萨特，哲学史第一次变得像侦探小说一样迷人。', '豆瓣', 5.0, '正面', 0.88, '哲学,启蒙,侦探', '席德之父', 654, 112, '2026-09-24 16:30:00'),
(26, '「你是谁」「世界从何而来」两封信开场就抓人，读到「少校的小木屋」章节时会起鸡皮疙瘩，结构太妙。', '知乎', 5.0, '正面', 0.85, '结构,悬念,惊喜', '镜中红匣子', 498, 88, '2026-09-28 10:45:00'),
(26, '哲学史部分讲得通俗，但小说性偏弱，人物像哲学课的提线木偶，中段课业密集时有点像在读教材。', '微信读书', 3.5, '中性', 0.50, '通俗,木偶,教材', '存在主义小姐', 312, 95, '2026-10-02 14:20:00'),
(26, '十四岁读被故事吸引，二十四岁重读被哲学震撼，这本书的年龄适配是终身的，每个阶段都读出新东西。', '小红书', 5.0, '正面', 0.87, '重读,震撼,终身', '白兔毛发梢', 423, 69, '2026-10-06 17:35:00'),
(26, '西方中心明显，东方哲学几笔带过，女性哲学家人数可怜，作为通史取舍有偏，当小说看趣味性尚可。', '知乎', 3.0, '中性', 0.46, '西方中心,取舍,通史', '东方哲学党', 267, 121, '2026-10-10 09:50:00'),
(26, '简化和戏说太多，哲学门类浮光掠影，童话包装下干货密度其实不高，不如直接读《大问题》。', '豆瓣', 2.5, '负面', 0.68, '戏说,干货,简化', '哲学发烧友', 213, 156, '2026-10-13 15:05:00'),
(26, '「魔术师帽子里的小白兔」比喻太经典了，保持好奇心的提醒贯穿全书，孩子和家长可以共读。', '微信读书', 4.5, '正面', 0.84, '比喻,好奇心,共读', '亲子阅读爸爸', 345, 58, '2026-10-17 11:20:00'),
(26, '结尾的「世界本身就是一个魔法」，让哲学课落回浪漫，少校与苏菲的双重虚构嵌套读到最后豁然开朗。', '知乎', 4.5, '正面', 0.83, '嵌套,虚构,浪漫', '上校的明信片', 298, 62, '2026-10-20 14:35:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(27, '无人不冤，有情皆孽。乔峰聚贤庄一战与雁门关自尽，是中文武侠里最悲壮的人物弧光，没有之一。', '豆瓣', 5.0, '正面', 0.92, '乔峰,悲壮,宿命', '降龙十八掌', 876, 186, '2026-09-25 12:00:00'),
(27, '三线叙事收放自如，段誉的痴、虚竹的憨、乔峰的义，三种性格三种命运交织成宏大的江湖画卷。', '知乎', 5.0, '正面', 0.87, '三线,命运,江湖', '大理世子', 567, 98, '2026-09-29 14:15:00'),
(27, '连载拼合痕迹有，王语嫣的人设前后矛盾，但单论乔峰线已是武侠天花板，瑕不掩瑜。', '微信读书', 3.5, '中性', 0.50, '连载,矛盾,天花板', '逍遥派弟子', 312, 85, '2026-10-03 17:30:00'),
(27, '少室山大战、藏经阁揭底，几场大戏群像调度精彩绝伦，慕容复的疯与萧峰的死对照读太唏嘘。', '小红书', 5.0, '正面', 0.90, '少室山,群像,唏嘘', '珍珑棋局', 498, 92, '2026-10-07 13:45:00'),
(27, '倪匡代笔那段确实跳戏（阿紫瞎眼的处理），整体收尾的高潮掩盖不了中段的小裂缝。', '知乎', 3.0, '中性', 0.47, '代笔,裂缝,高潮', '版本对照党', 245, 113, '2026-10-11 15:00:00'),
(27, '武功描写玄乎过头，段誉吸人内力基本无敌，主角光环下的反派全靠降智，武侠看多了都一样。', '豆瓣', 2.5, '负面', 0.68, '玄乎,光环,降智', '硬派武侠迷', 198, 167, '2026-10-14 16:15:00'),
(27, '「塞上牛羊空许约」，萧峰误杀阿朱是全书最痛一笔，金庸写爱情悲剧的功力登峰造极。', '微信读书', 5.0, '正面', 0.88, '阿朱,虐心,悲剧', '塞外牧羊人', 456, 78, '2026-10-18 12:30:00'),
(27, '佛学底色太深了，扫地僧点化萧远山慕容博那段，把一部武侠拔高到了哲思的高度，金庸封神之作。', '小红书', 5.0, '正面', 0.85, '佛学,扫地僧,哲思', '藏经阁扫地中', 512, 86, '2026-10-20 18:45:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(28, '童谣杀人+孤岛模式的开山鼻祖，十个人按儿歌顺序死亡的压迫感拉满，结局的凶手自白堪称神来之笔。', '豆瓣', 5.0, '正面', 0.91, '童谣,孤岛,凶手', '士兵岛村民', 712, 134, '2026-09-26 20:15:00'),
(28, '一口气读完根本停不下来，每死一个人氛围就紧一分，阿婆对群像心理的拿捏精准到可怕。', '知乎', 5.0, '正面', 0.87, '群像,心理,氛围', '侦探小说迷', 498, 82, '2026-09-30 13:30:00'),
(28, '诡计固然经典但依赖「不可能」的设定，部分人物动机经不起细想，读后回味不如过程精彩。', '微信读书', 3.5, '中性', 0.50, '诡计,设定,动机', '本格派考官', 287, 79, '2026-10-04 19:45:00'),
(28, '暴风雪山庄模板的教科书，印第安童谣的死亡预言与人体塑像的递减呼应，仪式感与恐惧感双重极致。', '小红书', 5.0, '正面', 0.89, '暴风雪山庄,预言,仪式', '收藏八座雕像', 456, 71, '2026-10-08 14:00:00'),
(28, '翻译腔有点重，人物名字一大堆需要记笔记，中段节奏稍拖，但结尾一章值回全部书价。', '知乎', 3.0, '中性', 0.48, '翻译腔,节奏,结尾', '欧文先生', 267, 94, '2026-10-12 16:15:00'),
(28, '被捧得太高了，凶手逻辑其实很勉强，漏洞摆在那，能畅销更多是模式开创性而不是解谜质量。', '豆瓣', 2.5, '负面', 0.65, '逻辑,漏洞,开创', '诡计流审稿人', 223, 178, '2026-10-15 10:30:00'),
(28, '法官的独白是全书灵魂，「我在道德与法律之间行走」，阿婆的凶手从来都有哲学味。', '微信读书', 4.5, '正面', 0.85, '法官,独白,哲学', '红发法官', 356, 63, '2026-10-18 17:45:00'),
(28, '读完立刻二刷，知道真相后再看每个人的言行全是伏笔，阿加莎的埋线能力真的绝。', '小红书', 5.0, '正面', 0.84, '二刷,伏笔,埋线', '二刷打卡中', 389, 57, '2026-10-21 11:00:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(29, '两百年来最聪明的爱情小说。伊丽莎白拒绝了两次求婚才换来真正的婚姻自由，在1813年难以想象。', '豆瓣', 5.0, '正面', 0.89, '爱情,自由,聪明', '彭伯里爱好者', 678, 112, '2026-09-27 12:15:00'),
(29, '班纳特太太的聒噪、柯林斯的谄媚，奥斯汀的讽刺永远精准又优雅，英式幽默的天花板。', '知乎', 5.0, '正面', 0.86, '讽刺,幽默,优雅', '尼日斐花园', 498, 78, '2026-10-01 14:30:00'),
(29, '时代局限明显，女性命运全系于婚姻，读起来甜多于思，当轻喜剧看更合适。', '微信读书', 3.5, '中性', 0.50, '时代,婚姻,轻喜剧', '理性婚恋观', 287, 92, '2026-10-05 15:45:00'),
(29, '达西的第二次求婚与伊丽莎白的自我反省——最好的爱情是彼此成长，而不是单方面的迁就。', '小红书', 5.0, '正面', 0.87, '达西,成长,反省', '简迷一枚', 456, 67, '2026-10-09 10:00:00'),
(29, '舞会、散步、串门、写信，情节密度低节奏慢，不喜欢古典文学的人会觉得无聊，慎入。', '知乎', 3.0, '中性', 0.46, '慢,无聊,古典', '现代快节奏党', 234, 108, '2026-10-13 11:15:00'),
(29, '本质是爽文：灰姑娘嫁贵族，还要求对方先自我改造，所谓的进步性放今天看也是慕强逻辑。', '豆瓣', 2.5, '负面', 0.65, '爽文,慕强,局限', '现代女性视角', 267, 198, '2026-10-16 12:30:00'),
(29, '「傲慢让别人无法爱我，偏见让我无法爱别人」，这句总结太精辟了，全书的人物弧光都装在这句话里。', '微信读书', 5.0, '正面', 0.85, '傲慢,偏见,弧光', '朗博恩读书会', 512, 83, '2026-10-19 13:45:00'),
(29, '最打动我的其实是伊丽莎白和简的姐妹情谊，在婚姻焦虑的时代彼此扶持，温柔又有力量。', '知乎', 4.5, '正面', 0.84, '姐妹,扶持,温柔', '长跑家的小妹', 342, 56, '2026-10-21 14:00:00');
INSERT INTO book_reviews (book_id, content, source, rating, sentiment, sentiment_score, keywords, author, like_count, reply_count, created_at) VALUES
(30, '用机器人的纯净视角看人类，反而照出了人心的复杂与自私。石黑一雄的笔一如既往地克制而深情。', '豆瓣', 5.0, '正面', 0.85, '机器人,视角,克制', 'AF观察日志', 512, 89, '2026-09-28 15:20:00'),
(30, '克拉拉对太阳的信仰像一种纯粹的祷告，乔西得救的真相温柔又残忍，读到最后一章心里空落落的。', '知乎', 5.0, '正面', 0.82, '太阳,信仰,真相', '橱窗里的AF', 423, 71, '2026-10-02 16:35:00'),
(30, '科幻设定其实很薄，AF技术语焉不详，重点全在伦理与情感，想看硬科幻的会失望，当成寓言读更好。', '微信读书', 3.5, '中性', 0.48, '设定,伦理,寓言', '硬核科幻党', 287, 104, '2026-10-06 17:50:00'),
(30, '「人心是可以学的吗？」克拉拉学得会爱与牺牲，却学不会人类的自相矛盾，诺奖作家的追问力透纸背。', '小红书', 5.0, '正面', 0.84, '人心,牺牲,追问', '太阳之子', 378, 62, '2026-10-10 19:05:00'),
(30, '节奏太慢了，日常细节铺得太多，中段一度想弃，好在结尾的悲剧感把全书的分量托住了。', '知乎', 3.0, '中性', 0.45, '慢,细节,悲剧', '没耐心读者', 234, 87, '2026-10-14 20:20:00'),
(30, '与前作《别让我走》相比毫无新意，AI视角也是老套路，石黑一雄在自我重复，名不副实。', '豆瓣', 2.5, '负面', 0.67, '重复,套路,失望', '黑一雄黑粉', 213, 152, '2026-10-17 21:35:00'),
(30, '母亲让克拉拉「替换」乔西的段落看得脊背发凉，关于爱与替代的悖论太扎心，人类真的值得被爱吗？', '微信读书', 4.5, '正面', 0.80, '替换,悖论,爱', '剧场里的父亲', 312, 68, '2026-10-20 22:50:00'),
(30, '堆场的结尾，克拉拉被「弃置」后依然感恩太阳，这种纯粹让人泪目，软科幻里的抒情诗。', '知乎', 4.5, '正面', 0.81, '弃置,感恩,抒情', '面包与太阳', 298, 54, '2026-10-21 16:05:00');
